def apply(seed):
    """미래 항목에 risk가 없으면 RISKS에서 붙인다. 근거 id가 claims에 없으면 오류."""
    claims = {c["id"] for c in seed["claims"]}
    groups = [("topic", seed["topics"]["topics"]), ("industry", seed["industries"]["industries"]), ("flow", seed["flows"]["flows"]), ("taste", seed["tastes"]["flows"])]
    used, missing = 0, []
    for kind, objs in groups:
        for o in objs:
            fs = o.get("futures")
            if not fs:
                continue
            for f in fs["items"]:
                if f.get("risk"):
                    continue
                r = RISKS.get((kind, o["id"], f["name"]))
                if not r:
                    missing.append(f"{kind}:{o['id']}:{f['name']}")
                    continue
                text, ids = r
                bad = [i for i in ids if i not in claims]
                assert not bad, (kind, o["id"], f["name"], bad)
                f["risk"] = {"layer": "inference", "text": text, "ids": list(ids)}
                used += 1
    seed["futureRisk"] = {"filled": used, "missing": missing}
    return seed
